using Provodnik.Features.ModOrganizer;

namespace Provodnik.Tests
{
  /// <summary>
  /// A mescla do perfil do GAMMA. Lembrete do formato: o modlist.txt é de trás pra frente (a primeira linha é a última
  /// no MO2, a de prioridade mais alta) e o separador vem depois dos mods dele.
  /// </summary>
  public sealed class ProfileMergeTests
  {
    private const string Mine = "Meus mods_separator";

    private static readonly string[] Gamma =
    [
      "# This file was automatically generated by Mod Organizer.",
      "-End",
      "+G.A.M.M.A. End of List_separator",
      "+3- Luz - Bia",
      "+2- Som - Ana",
      "+1- Audio_separator",
    ];

    /// <param name="owners">De quem é cada pasta fora da lista; quem não está aqui não tem pasta.</param>
    private static ProfileMergeResult Merge(string[] gamma, string[]? previous, string[]? current, Dictionary<string, ModOwner>? owners = null, string[]? gammaFolders = null) =>
      ProfileMerge.Merge(
        string.Join("\n", gamma),
        previous is null ? null : string.Join("\n", previous),
        current is null ? null : string.Join("\n", current),
        name => owners?.GetValueOrDefault(name) ?? ModOwner.None,
        gammaFolders ?? [],
        Mine,
        [Mine, "My mods_separator"]);

    private static Dictionary<string, ModOwner> Users(params string[] names) => names.ToDictionary(n => n, _ => ModOwner.User);

    private static string[] Lines(ProfileMergeResult result) => result.Text.Split('\n');

    [Fact]
    public void Perfil_novo_recebe_a_lista_do_GAMMA()
    {
      var result = Merge(Gamma, null, null);

      Assert.Equal(Gamma, Lines(result));
      Assert.Null(result.Separator);
    }

    [Fact]
    public void Mods_da_pessoa_vao_pro_fim_do_MO2_embaixo_de_Meus_mods_com_o_estado_deles()
    {
      // como o launcher original deixa: a lista do GAMMA por cima e os mods da pessoa misturados no meio
      string[] current = ["# This file was automatically generated by Mod Organizer.", "-End", "+G.A.M.M.A. End of List_separator", "-Shuler", "+3- Luz - Bia", "+Coop", "+2- Som - Ana", "+1- Audio_separator"];

      var result = Merge(Gamma, Gamma, current, Users("Shuler", "Coop"));

      Assert.Equal(
        ["# This file was automatically generated by Mod Organizer.", "-Shuler", "+Coop", "+" + Mine, "-End", "+G.A.M.M.A. End of List_separator", "+3- Luz - Bia", "+2- Som - Ana", "+1- Audio_separator"],
        Lines(result));
      Assert.Equal(["Shuler", "Coop"], result.KeptMods);
      Assert.Equal(Mine, result.Separator);
    }

    [Fact]
    public void Mod_do_GAMMA_que_a_pessoa_desligou_continua_desligado()
    {
      string[] current = ["-End", "+G.A.M.M.A. End of List_separator", "+3- Luz - Bia", "-2- Som - Ana", "+1- Audio_separator"];

      var result = Merge(Gamma, Gamma, current);

      Assert.Contains("-2- Som - Ana", Lines(result));
      Assert.Equal(["2- Som - Ana"], result.KeptChoices);
      Assert.Null(result.Separator);
    }

    [Fact]
    public void Mod_que_o_GAMMA_ligou_agora_entra_ligado()
    {
      string[] previous = ["-End", "+G.A.M.M.A. End of List_separator", "+3- Luz - Bia", "-2- Som - Ana", "+1- Audio_separator"];

      var result = Merge(Gamma, previous, previous);

      Assert.Contains("+2- Som - Ana", Lines(result));
      Assert.Empty(result.KeptChoices);
    }

    [Fact]
    public void Sem_a_lista_de_antes_os_do_GAMMA_seguem_a_lista_nova()
    {
      string[] current = ["-End", "+G.A.M.M.A. End of List_separator", "+3- Luz - Bia", "-2- Som - Ana", "+1- Audio_separator", "+Shuler"];

      var result = Merge(Gamma, null, current, Users("Shuler"));

      Assert.Contains("+2- Som - Ana", Lines(result));
      Assert.Equal(["Shuler"], result.KeptMods);
    }

    [Fact]
    public void Mod_que_saiu_do_GAMMA_vai_desligado_pro_comeco_do_MO2()
    {
      // a pasta do mod velho ainda existe e não tem a marca do GAMMA, mas ele estava na lista de antes
      string[] previous = [.. Gamma, "+4- Velho - Caio"];

      var result = Merge(Gamma, previous, previous, Users("4- Velho - Caio"));

      Assert.Equal([.. Gamma, "-4- Velho - Caio"], Lines(result));
      Assert.Empty(result.KeptMods);
      Assert.Null(result.Separator);
    }

    [Fact]
    public void Linha_sem_pasta_nao_volta()
    {
      string[] current = ["+Sumiu", .. Gamma];

      var result = Merge(Gamma, Gamma, current);

      Assert.Equal(Gamma, Lines(result));
    }

    [Fact]
    public void Opcional_do_GAMMA_que_a_pessoa_ligou_fica_com_os_mods_dela()
    {
      string[] current = ["+Sky Fix", "-Bushes Dead", .. Gamma.Skip(1)];
      var owners = new Dictionary<string, ModOwner> { ["Sky Fix"] = ModOwner.GammaOptional, ["Bushes Dead"] = ModOwner.GammaOptional };

      var result = Merge(Gamma, Gamma, current, owners);

      // o desligado é sobra: vai pro começo do MO2, longe dos dela
      Assert.Equal([Gamma[0], "+Sky Fix", "+" + Mine, .. Gamma.Skip(1), "-Bushes Dead"], Lines(result));
      Assert.Equal(["Sky Fix"], result.KeptMods);
    }

    [Fact]
    public void Opcional_que_estava_na_lista_e_saiu_volta_desligado()
    {
      string[] previous = ["+Sky Fix", .. Gamma.Skip(1)];

      var result = Merge(Gamma, previous, previous, new Dictionary<string, ModOwner> { ["Sky Fix"] = ModOwner.GammaOptional });

      Assert.Equal([.. Gamma, "-Sky Fix"], Lines(result));
      Assert.Empty(result.KeptMods);
    }

    [Fact]
    public void Sobra_do_GAMMA_sem_linha_ganha_linha_desligada_no_comeco_do_MO2()
    {
      // sem linha, o MO2 poria a pasta no fim da lista dele, dentro do "Meus mods"
      var result = Merge(Gamma, Gamma, Gamma, gammaFolders: ["Zeta Addon", "Alfa Addon", "3- Luz - Bia"]);

      Assert.Equal([.. Gamma, "-Alfa Addon", "-Zeta Addon"], Lines(result));
    }

    [Fact]
    public void Sobras_ficam_antes_da_linha_vazia_do_fim()
    {
      var result = ProfileMerge.Merge("+2- Som - Ana\r\n", null, null, _ => ModOwner.None, ["Velho"], Mine, [Mine]);

      Assert.Equal("+2- Som - Ana\r\n-Velho\r\n", result.Text);
    }

    [Fact]
    public void Separador_da_pessoa_no_fim_do_bloco_ja_agrupa()
    {
      string[] current = ["+Shuler", "+Coop", "+Minhas coisas_separator", .. Gamma.Skip(1)];

      var result = Merge(Gamma, Gamma, current, Users("Shuler", "Coop", "Minhas coisas_separator"));

      Assert.Equal([Gamma[0], "+Shuler", "+Coop", "+Minhas coisas_separator", .. Gamma.Skip(1)], Lines(result));
      Assert.Equal(["Shuler", "Coop"], result.KeptMods);
      Assert.Null(result.Separator);
    }

    [Fact]
    public void Separador_da_pessoa_no_meio_ganha_o_Meus_mods_no_fim()
    {
      // no MO2: ... Coop, Minhas coisas, Shuler. O Coop ficaria no separador do GAMMA sem o "Meus mods"
      string[] current = ["+Shuler", "+Minhas coisas_separator", "+Coop", .. Gamma.Skip(1)];

      var result = Merge(Gamma, Gamma, current, Users("Shuler", "Coop", "Minhas coisas_separator"));

      Assert.Equal(["+Shuler", "+Minhas coisas_separator", "+Coop", "+" + Mine, "-End"], Lines(result)[1..6]);
    }

    [Fact]
    public void Meus_mods_em_outro_idioma_continua_com_o_nome_dele()
    {
      string[] current = ["+Shuler", "+My mods_separator", .. Gamma.Skip(1)];

      var result = Merge(Gamma, Gamma, current, Users("Shuler"));

      Assert.Equal(["+Shuler", "+My mods_separator", "-End"], Lines(result)[1..4]);
      Assert.Equal("My mods_separator", result.Separator);
      Assert.DoesNotContain("+" + Mine, Lines(result));
    }

    [Fact]
    public void Meus_mods_vazio_continua_pra_receber_os_proximos()
    {
      string[] current = ["+" + Mine, .. Gamma.Skip(1)];

      var result = Merge(Gamma, Gamma, current);

      Assert.Equal(["+" + Mine, "-End"], Lines(result)[1..3]);
      Assert.Empty(result.KeptMods);
    }

    [Fact]
    public void Rodar_de_novo_da_o_mesmo_texto()
    {
      string[] current = ["-End", "+G.A.M.M.A. End of List_separator", "-Shuler", "+3- Luz - Bia", "+Coop", "-2- Som - Ana", "+1- Audio_separator", "-Velho"];
      var owners = Users("Shuler", "Coop");
      owners["Velho"] = ModOwner.Gamma;
      owners["Opcional"] = ModOwner.GammaOptional;

      var first = Merge(Gamma, Gamma, current, owners, ["Velho", "Opcional"]);
      var second = Merge(Gamma, Gamma, Lines(first), owners, ["Velho", "Opcional"]);

      Assert.Equal(first.Text, second.Text);
      Assert.Equal(["2- Som - Ana"], second.KeptChoices);
    }

    [Fact]
    public void Quebra_de_linha_e_TAB_do_GAMMA_ficam()
    {
      // o modlist do GAMMA tem nome com TAB no fim (#425)
      var gamma = "# MO2\r\n+2- Som - Ana\t\r\n+1- Audio_separator\r\n";
      var result = ProfileMerge.Merge(gamma, gamma, "-2- Som - Ana\n+1- Audio_separator\n+Shuler\n", name => name == "Shuler" ? ModOwner.User : ModOwner.None, [], Mine, [Mine]);

      Assert.Equal("# MO2\r\n+Shuler\r\n+" + Mine + "\r\n-2- Som - Ana\t\r\n+1- Audio_separator\r\n", result.Text);
    }

    [Fact]
    public void Linha_repetida_no_perfil_entra_uma_vez()
    {
      string[] current = ["+Shuler", "-Shuler", .. Gamma.Skip(1)];

      var result = Merge(Gamma, Gamma, current, Users("Shuler"));

      Assert.Single(Lines(result), l => l.EndsWith("Shuler", StringComparison.Ordinal));
      Assert.Contains("+Shuler", Lines(result));
    }
  }
}
